export interface SubtitleBlock {
  id: number;
  startTime: string;
  endTime: string;
  text: string;
}

export enum TranslationStatus {
  IDLE = 'IDLE',
  PARSING = 'PARSING',
  TRANSLATING = 'TRANSLATING',
  RETRYING = 'RETRYING',
  COMPLETED = 'COMPLETED',
  ERROR = 'ERROR'
}

export interface LanguageOption {
  code: string;
  name: string;
}

export interface ModelOption {
  id: string;
  name: string;
  description: string;
}

export const MODELS: ModelOption[] = [
  { id: 'gemini-3-flash-preview', name: 'Gemini 3 Flash', description: 'Fastest & Latest' },
  { id: 'gemini-3-pro-preview', name: 'Gemini 3 Pro', description: 'Deepest Reasoning' },
  { id: 'gemini-2.5-pro-preview', name: 'Gemini 2.5 Pro', description: 'Advanced Quality' },
  { id: 'gemini-2.5-flash', name: 'Gemini 2.5 Flash', description: 'Efficient & Reliable' },
];

export const LANGUAGES: LanguageOption[] = [
  { code: 'vi', name: 'Vietnamese' },
  { code: 'en', name: 'English' },
  { code: 'es', name: 'Spanish' },
  { code: 'fr', name: 'French' },
  { code: 'de', name: 'German' },
  { code: 'ja', name: 'Japanese' },
  { code: 'ko', name: 'Korean' },
  { code: 'zh', name: 'Chinese (Simplified)' },
  { code: 'ru', name: 'Russian' },
  { code: 'pt', name: 'Portuguese' },
  { code: 'it', name: 'Italian' },
  { code: 'id', name: 'Indonesian' },
  { code: 'th', name: 'Thai' },
];

import { GoogleGenAI, Type } from "@google/genai";

// Helper for exponential backoff
const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

const getClient = (apiKey?: string) => new GoogleGenAI({ apiKey: apiKey || process.env.API_KEY });

export const translateBatch = async (
  texts: string[],
  sourceLang: string,
  targetLang: string,
  model: string = 'gemini-3-flash-preview',
  onRetry?: (attempt: number, delayMs: number) => void
): Promise<string[]> => {
  if (texts.length === 0) return [];

  const ai = getClient();
  const MAX_RETRIES = 3;
  let attempt = 0;

  // Define a prompt that encourages brevity and subtitle formatting
  const prompt = `
    You are a professional subtitle translator. 
    Translate the following array of subtitle text segments from ${sourceLang === 'auto' ? 'the detected language' : sourceLang} to ${targetLang}.

    Rules:
    1. Maintain the tone and context.
    2. Keep translations concise to fit within standard subtitle limits where possible.
    3. Do not add any introductory or concluding text.
    4. Return exactly the same number of items in the array as provided.
    5. Preserve any HTML tags like <i> or <b> if present.

    Input texts:
    ${JSON.stringify(texts)}
  `;

  while (attempt <= MAX_RETRIES) {
    try {
      const response = await ai.models.generateContent({
        model: model,
        contents: prompt,
        config: {
          responseMimeType: "application/json",
          responseSchema: {
            type: Type.ARRAY,
            items: { type: Type.STRING },
          }
        }
      });

      const jsonText = response.text;
      if (!jsonText) {
        throw new Error("Empty response from Gemini");
      }

      const translatedArray = JSON.parse(jsonText);

      if (!Array.isArray(translatedArray)) {
          throw new Error("Invalid response format");
      }

      // Fallback: if lengths mismatch, we return original to avoid desync
      if (translatedArray.length !== texts.length) {
        console.warn(`Mismatch in translation count. Sent ${texts.length}, received ${translatedArray.length}. Padding with originals.`);
        return texts.map((orig, i) => translatedArray[i] || orig);
      }

      return translatedArray;

    } catch (error: any) {
      // Check for rate limit errors (429) or service overload (503)
      const isRateLimit = error.message?.includes('429') || error.status === 429;
      const isServiceUnavailable = error.message?.includes('503') || error.status === 503;

      if ((isRateLimit || isServiceUnavailable) && attempt < MAX_RETRIES) {
        attempt++;
        // Exponential backoff: 2s, 4s, 8s
        const delayMs = Math.pow(2, attempt) * 1000;

        if (onRetry) {
          onRetry(attempt, delayMs);
        }

        console.warn(`Attempt ${attempt} failed with rate limit. Retrying in ${delayMs}ms...`);
        await delay(delayMs);
        continue;
      }

      console.error("Translation error:", error);

      return texts; 
    }
  }

  return texts;
};

import React, { useState } from 'react';
import { FileText, ArrowRight, Download, RefreshCw, Globe, CheckCircle2, AlertCircle, Zap, Cpu, Loader2, ListOrdered, X } from 'lucide-react';
import FileUploader from './components/FileUploader';
import { parseSRT, generateSRT, renumberSubtitles, parseASS, generateASS, AssMeta } from './utils/srtParser';
import { translateBatch } from './services/geminiService';
import { SubtitleBlock, LANGUAGES, TranslationStatus, MODELS, ModelOption } from './types';

// How many subtitles to send to Gemini at once
const BATCH_SIZE = 40;

const App: React.FC = () => {
  const [fileName, setFileName] = useState<string | null>(null);
  const [fileType, setFileType] = useState<'srt' | 'ass'>('srt');
  const [assMeta, setAssMeta] = useState<AssMeta | null>(null);

  const [originalSubtitles, setOriginalSubtitles] = useState<SubtitleBlock[]>([]);
  const [translatedSubtitles, setTranslatedSubtitles] = useState<SubtitleBlock[]>([]);

  const [sourceLang, setSourceLang] = useState<string>('auto');
  const [targetLang, setTargetLang] = useState<string>('vi');
  const [selectedModel, setSelectedModel] = useState<string>(MODELS[0].id);

  const [status, setStatus] = useState<TranslationStatus>(TranslationStatus.IDLE);
  const [progress, setProgress] = useState<number>(0);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [retryCount, setRetryCount] = useState<number>(0);

  // Renumbering State
  const [showRenumberModal, setShowRenumberModal] = useState(false);
  const [renumberStart, setRenumberStart] = useState<number>(1);

  const handleFileLoaded = (content: string, name: string) => {
    try {
      setStatus(TranslationStatus.PARSING);
      setErrorMsg(null);

      let parsed: SubtitleBlock[] = [];

      if (name.toLowerCase().endsWith('.ass')) {
        const result = parseASS(content);
        parsed = result.blocks;
        setAssMeta(result.meta);
        setFileType('ass');
      } else {
        parsed = parseSRT(content);
        setFileType('srt');
        setAssMeta(null);
      }

      if (parsed.length === 0) {
        throw new Error("No valid subtitles found in file.");
      }
      setOriginalSubtitles(parsed);
      setFileName(name);
      setTranslatedSubtitles([]); // Reset previous translations
      setStatus(TranslationStatus.IDLE);
    } catch (e) {
      console.error(e);
      setErrorMsg("Failed to parse subtitle file. Please check the format.");
      setStatus(TranslationStatus.ERROR);
    }
  };

  const handleTranslate = async () => {
    if (originalSubtitles.length === 0) return;

    setStatus(TranslationStatus.TRANSLATING);
    setProgress(0);
    setErrorMsg(null);
    setRetryCount(0);

    let currentTranslations: SubtitleBlock[] = [...originalSubtitles]; // Start with a copy

    try {
      for (let i = 0; i < originalSubtitles.length; i += BATCH_SIZE) {
        const batch = originalSubtitles.slice(i, i + BATCH_SIZE);
        const textsToTranslate = batch.map(b => b.text);

        const translatedTexts = await translateBatch(
          textsToTranslate, 
          sourceLang, 
          targetLang, 
          selectedModel,
          (attempt, delayMs) => {
            // Update UI to show retry status
            setStatus(TranslationStatus.RETRYING);
            setRetryCount(attempt);
          }
        );

        // Reset status back to translating if it was retrying
        setStatus(TranslationStatus.TRANSLATING);
        setRetryCount(0);

        // Update local variable
        batch.forEach((block, idx) => {
            const globalIndex = i + idx;
            if (currentTranslations[globalIndex]) {
                currentTranslations[globalIndex] = {
                    ...currentTranslations[globalIndex],
                    text: translatedTexts[idx] || block.text // Fallback to original
                };
            }
        });

        setTranslatedSubtitles([...currentTranslations]);
        setProgress(Math.round(((i + batch.length) / originalSubtitles.length) * 100));
      }

      setStatus(TranslationStatus.COMPLETED);
    } catch (e) {
      console.error(e);
      setErrorMsg("An error occurred during translation. Try switching models if quota is exceeded.");
      setStatus(TranslationStatus.ERROR);
    }
  };

  const handleRenumber = () => {
    if (originalSubtitles.length === 0) return;

    const newOriginals = renumberSubtitles(originalSubtitles, renumberStart);
    setOriginalSubtitles(newOriginals);

    if (translatedSubtitles.length > 0) {
      const newTranslated = renumberSubtitles(translatedSubtitles, renumberStart);
      setTranslatedSubtitles(newTranslated);
    }

    setShowRenumberModal(false);
  };

  const handleDownload = () => {
    const subtitlesToSave = translatedSubtitles.length > 0 ? translatedSubtitles : originalSubtitles;
    let content = '';
    let ext = '';

    if (fileType === 'ass' && assMeta) {
        content = generateASS(subtitlesToSave, assMeta);
        ext = '.ass';
    } else {
        content = generateSRT(subtitlesToSave);
        ext = '.srt';
    }

    const blob = new Blob([content], { type: 'text/plain' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    const originalName = fileName || 'subtitles';
    const nameWithoutExt = originalName.lastIndexOf('.') !== -1 
        ? originalName.substring(0, originalName.lastIndexOf('.')) 
        : originalName;

    const newName = `${nameWithoutExt}_${targetLang}${ext}`;

    link.href = url;
    link.download = newName;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const reset = () => {
    setFileName(null);
    setFileType('srt');
    setAssMeta(null);
    setOriginalSubtitles([]);
    setTranslatedSubtitles([]);
    setStatus(TranslationStatus.IDLE);
    setProgress(0);
    setErrorMsg(null);
  };

  return (
    <div className="min-h-screen bg-slate-950 text-slate-200 pb-20 relative">
      {/* Header */}
      <header className="border-b border-slate-800 bg-slate-950/50 backdrop-blur-md sticky top-0 z-40">
        <div className="container mx-auto px-4 h-16 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <div className="w-8 h-8 bg-gradient-to-br from-primary-500 to-purple-600 rounded-lg flex items-center justify-center shadow-lg shadow-primary-500/20">
              <Zap className="w-5 h-5 text-white" />
            </div>
            <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
              SubStream AI
            </h1>
          </div>
          <div className="text-sm text-slate-500 font-medium hidden md:block">
            Powered by Gemini
          </div>
        </div>
      </header>

      <main className="container mx-auto px-4 py-8">

        {/* Hero / Intro */}
        {status === TranslationStatus.IDLE && !fileName && (
          <div className="text-center max-w-2xl mx-auto mb-12 mt-8">
            <h2 className="text-4xl font-bold text-white mb-4 tracking-tight">
              Translate Subtitles instantly.
            </h2>
            <p className="text-slate-400 text-lg mb-8">
              Upload your .srt or .ass files and let our AI handle the context-aware translation. Supports auto-retry for high reliability.
            </p>
          </div>
        )}

        {/* Upload Section */}
        {!fileName && <FileUploader onFileLoaded={handleFileLoaded} />}

        {/* Main Workspace */}
        {fileName && (
          <div className="animate-fade-in">
            {/* Toolbar */}
            <div className="bg-slate-900 rounded-xl border border-slate-800 p-4 mb-6 flex flex-col xl:flex-row items-center justify-between gap-4 shadow-xl">

              {/* File Info */}
              <div className="flex items-center gap-3 w-full xl:w-auto overflow-hidden">
                <div className="bg-slate-800 p-2 rounded-lg min-w-fit">
                   <FileText className="text-primary-400 w-5 h-5" />
                </div>
                <div className="flex flex-col overflow-hidden">
                    <span className="font-mono text-sm text-slate-300 truncate max-w-[150px]" title={fileName}>
                    {fileName}
                    </span>
                    <span className="text-[10px] text-slate-500 font-semibold uppercase">{fileType} FILE</span>
                </div>
                <span className="text-xs px-2 py-1 bg-slate-800 rounded-full text-slate-400 whitespace-nowrap ml-2">
                  {originalSubtitles.length} lines
                </span>
              </div>

              {/* Controls */}
              <div className="flex flex-wrap items-center gap-3 w-full xl:w-auto justify-center">

                {/* Model Selector */}
                <div className="relative group">
                  <div className="absolute left-3 top-2.5 z-10 text-slate-500">
                    <Cpu className="w-4 h-4" />
                  </div>
                  <select 
                    value={selectedModel}
                    onChange={(e) => setSelectedModel(e.target.value)}
                    disabled={status === TranslationStatus.TRANSLATING || status === TranslationStatus.RETRYING}
                    className="appearance-none bg-slate-950 border border-slate-700 text-white py-2 pl-10 pr-10 rounded-lg text-sm focus:ring-2 focus:ring-primary-500 focus:outline-none disabled:opacity-50 hover:border-slate-600 transition-colors w-48 cursor-pointer"
                  >
                    {MODELS.map(m => (
                      <option key={m.id} value={m.id}>{m.name}</option>
                    ))}
                  </select>
                  <div className="absolute right-3 top-2.5 pointer-events-none text-slate-500">
                    <ArrowRight className="w-3 h-3 rotate-90" />
                  </div>
                </div>

                <div className="h-8 w-px bg-slate-800 hidden md:block"></div>

                {/* Source Lang */}
                <div className="relative group">
                  <select 
                    value={sourceLang}
                    onChange={(e) => setSourceLang(e.target.value)}
                    disabled={status === TranslationStatus.TRANSLATING || status === TranslationStatus.RETRYING}
                    className="appearance-none bg-slate-950 border border-slate-700 text-white py-2 pl-4 pr-10 rounded-lg text-sm focus:ring-2 focus:ring-primary-500 focus:outline-none disabled:opacity-50 hover:border-slate-600 transition-colors w-32 cursor-pointer"
                  >
                    <option value="auto">Auto Detect</option>
                    {LANGUAGES.map(l => <option key={`source-${l.code}`} value={l.name}>{l.name}</option>)}
                  </select>
                  <Globe className="absolute right-3 top-2.5 w-4 h-4 text-slate-500 pointer-events-none" />
                </div>

                <ArrowRight className="text-slate-600 w-4 h-4" />

                {/* Target Lang */}
                <div className="relative">
                  <select 
                    value={targetLang}
                    onChange={(e) => setTargetLang(e.target.value)}
                    disabled={status === TranslationStatus.TRANSLATING || status === TranslationStatus.RETRYING}
                    className="appearance-none bg-slate-950 border border-slate-700 text-white py-2 pl-4 pr-10 rounded-lg text-sm focus:ring-2 focus:ring-primary-500 focus:outline-none disabled:opacity-50 hover:border-slate-600 transition-colors w-32 cursor-pointer"
                  >
                    {LANGUAGES.map(l => <option key={`target-${l.code}`} value={l.code}>{l.name}</option>)}
                  </select>
                  <Globe className="absolute right-3 top-2.5 w-4 h-4 text-slate-500 pointer-events-none" />
                </div>
              </div>

              {/* Actions */}
              <div className="flex items-center gap-2 w-full xl:w-auto">
                {(status === TranslationStatus.IDLE || status === TranslationStatus.COMPLETED || status === TranslationStatus.ERROR) ? (
                  <>
                    {status !== TranslationStatus.COMPLETED ? (
                        <button 
                            onClick={handleTranslate}
                            className="flex-1 xl:flex-none bg-primary-600 hover:bg-primary-500 text-white px-6 py-2 rounded-lg font-medium transition-all flex items-center justify-center gap-2 shadow-lg shadow-primary-900/20"
                        >
                            <RefreshCw className="w-4 h-4" />
                            Translate
                        </button>
                    ) : (
                        <button 
                            onClick={handleDownload}
                            className="flex-1 xl:flex-none bg-emerald-600 hover:bg-emerald-500 text-white px-6 py-2 rounded-lg font-medium transition-all flex items-center justify-center gap-2 shadow-lg shadow-emerald-900/20"
                        >
                            <Download className="w-4 h-4" />
                            Download
                        </button>
                    )}

                    <button 
                      onClick={() => setShowRenumberModal(true)}
                      className="px-3 py-2 text-slate-400 hover:text-white transition-colors"
                      title="Renumber Subtitles"
                    >
                        <ListOrdered className="w-5 h-5" />
                    </button>

                    <button 
                      onClick={reset}
                      className="px-3 py-2 text-slate-400 hover:text-white transition-colors"
                      title="Reset"
                    >
                        Reset
                    </button>
                  </>
                ) : (
                  <div className="flex-1 xl:flex-none px-6 py-2 flex items-center gap-3 bg-slate-800 rounded-lg border border-slate-700">
                    {status === TranslationStatus.RETRYING ? (
                      <>
                         <Loader2 className="w-4 h-4 text-amber-400 animate-spin" />
                         <span className="text-sm text-amber-400 font-medium">Retrying ({retryCount})...</span>
                      </>
                    ) : (
                      <>
                        <div className="w-4 h-4 border-2 border-primary-500 border-t-transparent rounded-full animate-spin"></div>
                        <span className="text-sm text-slate-300 font-medium">Translating...</span>
                      </>
                    )}
                  </div>
                )}
              </div>
            </div>

            {/* Progress Bar */}
            {(status === TranslationStatus.TRANSLATING || status === TranslationStatus.RETRYING || status === TranslationStatus.COMPLETED) && (
              <div className="w-full bg-slate-800 h-1.5 rounded-full mb-6 overflow-hidden relative">
                <div 
                  className={`h-full transition-all duration-300 ease-out ${status === TranslationStatus.RETRYING ? 'bg-amber-500' : 'bg-primary-500'}`}
                  style={{ width: `${progress}%` }}
                ></div>
              </div>
            )}

            {/* Error Message */}
            {errorMsg && (
              <div className="bg-red-500/10 border border-red-500/20 text-red-400 p-4 rounded-xl mb-6 flex items-center gap-3">
                <AlertCircle className="w-5 h-5" />
                {errorMsg}
              </div>
            )}

            {/* Comparison View */}
            <div className="grid md:grid-cols-2 gap-6 h-[600px]">
              {/* Original */}
              <div className="flex flex-col h-full">
                <h3 className="text-slate-400 font-medium mb-3 px-1 uppercase text-xs tracking-wider">Original</h3>
                <div className="bg-slate-900 rounded-xl border border-slate-800 flex-1 overflow-y-auto p-4 space-y-4">
                  {originalSubtitles.map((sub) => (
                    <div key={`orig-${sub.id}`} className="group hover:bg-slate-800/50 p-2 rounded-lg transition-colors">
                      <div className="flex justify-between text-xs text-slate-500 font-mono mb-1">
                        <span>#{sub.id}</span>
                        <span>{sub.startTime} - {sub.endTime}</span>
                      </div>
                      <p className="text-slate-300 leading-relaxed whitespace-pre-wrap">{sub.text}</p>
                    </div>
                  ))}
                </div>
              </div>

              {/* Translated */}
              <div className="flex flex-col h-full">
                <div className="flex items-center justify-between mb-3 px-1">
                    <div className="flex items-center gap-2">
                      <h3 className="text-primary-400 font-medium uppercase text-xs tracking-wider">Translated</h3>
                      <span className="text-[10px] px-1.5 py-0.5 rounded bg-slate-800 text-slate-400 border border-slate-700">
                        {MODELS.find(m => m.id === selectedModel)?.name}
                      </span>
                    </div>
                    {status === TranslationStatus.COMPLETED && (
                        <span className="text-xs text-emerald-400 flex items-center gap-1">
                            <CheckCircle2 className="w-3 h-3" />
                            Done
                        </span>
                    )}
                </div>
                <div className="bg-slate-900 rounded-xl border border-slate-800 flex-1 overflow-y-auto p-4 space-y-4 relative">
                  {translatedSubtitles.length === 0 && status !== TranslationStatus.TRANSLATING && status !== TranslationStatus.RETRYING ? (
                    <div className="absolute inset-0 flex flex-col items-center justify-center text-slate-600">
                        <Globe className="w-12 h-12 mb-3 opacity-20" />
                        <p className="text-sm">Translation will appear here</p>
                    </div>
                  ) : (
                    (translatedSubtitles.length > 0 ? translatedSubtitles : originalSubtitles).map((sub, idx) => (
                        <div key={`trans-${sub.id}`} className="group hover:bg-slate-800/50 p-2 rounded-lg transition-colors">
                            <div className="flex justify-between text-xs text-slate-500 font-mono mb-1">
                                <span>#{sub.id}</span>
                                <span>{sub.startTime} - {sub.endTime}</span>
                            </div>
                            <p className={`leading-relaxed whitespace-pre-wrap ${translatedSubtitles[idx] ? 'text-emerald-100' : 'text-slate-600 blur-[2px]'}`}>
                                {translatedSubtitles[idx] ? translatedSubtitles[idx].text : sub.text}
                            </p>
                        </div>
                    ))
                  )}
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Renumber Modal */}
      {showRenumberModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4 animate-fade-in">
            <div className="bg-slate-900 border border-slate-700 rounded-xl p-6 w-full max-w-sm shadow-2xl relative">
                <button 
                  onClick={() => setShowRenumberModal(false)}
                  className="absolute top-4 right-4 text-slate-500 hover:text-white"
                >
                  <X className="w-4 h-4" />
                </button>
                <h3 className="text-lg font-semibold text-white mb-4 flex items-center gap-2">
                    <ListOrdered className="w-5 h-5 text-primary-400" />
                    Renumber Subtitles
                </h3>
                <div className="mb-6">
                    <label className="block text-sm text-slate-400 mb-2">Start Number</label>
                    <input 
                        type="number" 
                        value={renumberStart}
                        onChange={(e) => setRenumberStart(parseInt(e.target.value) || 1)}
                        className="w-full bg-slate-950 border border-slate-700 text-white rounded-lg px-3 py-2 focus:ring-2 focus:ring-primary-500 outline-none transition-all"
                        min="0"
                    />
                    <p className="text-xs text-slate-500 mt-2">
                        This will sequentially reassign IDs for all subtitle blocks starting from the number above.
                    </p>
                </div>
                <div className="flex justify-end gap-3">
                    <button 
                        onClick={() => setShowRenumberModal(false)}
                        className="px-4 py-2 text-slate-400 hover:text-white transition-colors text-sm font-medium"
                    >
                        Cancel
                    </button>
                    <button 
                        onClick={handleRenumber}
                        className="px-4 py-2 bg-primary-600 hover:bg-primary-500 text-white rounded-lg text-sm font-medium shadow-lg shadow-primary-900/20"
                    >
                        Apply Changes
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

export default App;
